var n=`1194-hilachas`;var t=`world-1194`;var a=`GT`;var s=`central-america-caribbean`;var o=4;var r=161;var l={en:`Hilachas`,ua:`Ілачас`};var d={en:`Hilachas is a dish from Guatemala prepared with beef flank steak, yellow onion, garlic, tomato. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Ілачас, страва кухні країни Гватемала, яку готують із таких продуктів: яловичий фланк-стейк, жовта цибуля, часник, помідор. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-flank-steak`,850,`g`],[`canola-oil`,40,`ml`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 105 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 105 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:105,i:[[`water`,850,`ml`],[`yellow-onion`,200,`g`],[`garlic`,5,`clove`]]},{en:`Shred the fully cooked meat into thin pieces with clean forks, discarding bones and tough connective tissue.`,ua:`Розберіть повністю приготоване м’ясо чистими виделками на тонкі волокна, видаливши кістки й жорсткі частини.`,t:[`shredding`,`mixing`],m:12,i:[]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`tomato`,400,`g`],[`red-bell-pepper`,260,`g`],[`ground-cumin`,5,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 20 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 20 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:20,i:[]}];var g={slug:n,id:t,country:`GT`,region:s,servings:4,minutes:161,title:l,text:d,steps:u};export{a as country,g as default,t as id,r as minutes,s as region,o as servings,n as slug,u as steps,d as text,l as title};